// Let's write a function to click each combination and collect (size, storage, color, price)
const testCombinations = await browserjs(tabId, async () => {
  const results = [];
  const sizes = ['11"', '13"'];
  const storages = ['128GB', '256GB', '512GB', '1TB'];
  const colors = ['Color, Space Gray', 'Color, Blue', 'Color, Purple', 'Color, Starlight'];

  for (const s of sizes) {
    const sBtn = Array.from(document.querySelectorAll('button')).find(b => b.innerText?.trim() === s);
    if (sBtn) sBtn.click();
    await new Promise(r => setTimeout(r, 400));

    for (const st of storages) {
      const stBtn = Array.from(document.querySelectorAll('button')).find(b => b.innerText?.trim() === st);
      if (stBtn) stBtn.click();
      await new Promise(r => setTimeout(r, 400));

      for (const c of colors) {
        const cBtn = Array.from(document.querySelectorAll('button')).find(b => b.getAttribute('aria-label')?.includes(c));
        if (cBtn) cBtn.click();
        await new Promise(r => setTimeout(r, 400));

        const priceEl = document.querySelector('[data-test="product-price"]') || document.querySelector('[data-test="@web/Price/Large"]');
        const h1 = document.querySelector('h1')?.innerText;
        const price = priceEl?.innerText || 'N/A';
        const url = window.location.href;
        results.push({ size: s, storage: st, color: c, price, h1, url });
      }
    }
  }
  return results;
});

