  return queries.map(q => ({
    queryKey: q.queryKey,
    data: q.state?.data
  }));
});

console.log("Queries count:", data ? data.length : 0);

// Let's find child items / variants and their prices
const variantInfo = await browserjs(tabId, () => {
  const scripts = Array.from(document.querySelectorAll('script'));
  const nextScript = scripts.find(s => s.id === '__NEXT_DATA__');
  if (!nextScript) return "No next data";
  const json = JSON.parse(nextScript.textContent);

  // Find all objects with tcin, price, or title
  const results = [];
  function search(obj) {
    if (!obj || typeof obj !== 'object') return;
    if (obj.tcin && obj.item?.product_description?.title) {
      results.push({
        tcin: obj.tcin,
        title: obj.item.product_description.title,
        price: obj.price,
        variation: obj.item.variation_info
      });
    }
    for (const key of Object.keys(obj)) {
      search(obj[key]);
    }
  }
  search(json);
  return results;
});

