const tabId = 2052873101;

// Let's inspect all configurations on the new iPad Air M3 page
// Let's navigate to the base URL
await tool.navigate({ tabId, url: "https://www.target.com/p/apple-ipad-air-m3-13-inch-wi-fi-128gb-space-gray/-/A-91122010" });
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 3000 });

// Check what sizes, storages, colors exist and their preselect URLs / prices
const variants = await browserjs(tabId, () => {
  // Check if there are JSON data or script tags with product info
  const scripts = Array.from(document.querySelectorAll('script[type="application/ld+json"], script[type="application/json"]'));
  const ldJson = scripts.map(s => {
    try { return JSON.parse(s.textContent); } catch (e) { return null; }
  }).filter(Boolean);

  // Also check window.__TGT_DATA__ or similar if present
  return {
    ldJson,
    buttons: Array.from(document.querySelectorAll('button')).map(b => ({
      text: b.innerText?.trim(),
      label: b.getAttribute('aria-label'),
      disabled: b.disabled,
      className: b.className
    })).filter(b => b.label || b.text)
  };
});

console.log("LD JSON items count:", variants.ldJson.length);
console.log("Relevant buttons:", variants.buttons.filter(b => 
  ['11"', '13"', '128GB', '256GB', '512GB', '1TB'].some(s => b.text === s || b.label?.includes(s)) ||
  b.label?.includes('Color')
));

