const testUrls = [
  "https://www.target.com/p/apple-ipad-air-m3-13-inch-wi-fi-128gb-space-gray/-/A-91122010?preselect=91122029", // 11" 128GB Space Gray
  "https://www.target.com/p/apple-ipad-air-m3-13-inch-wi-fi-128gb-space-gray/-/A-91122010?preselect=91121998", // 11" 128GB Blue
  "https://www.target.com/p/refurbished-apple-ipad-air-m3-11-inch-wi-fi-128gb-space-gray-target-certified-refurbished/-/A-94761293", // Refurb 11" 128GB Space Gray Excellent
  "https://www.target.com/p/refurbished-apple-ipad-air-m3-11-inch-wi-fi-128gb-space-gray-target-certified-refurbished/-/A-94761293?preselect=94761298" // Refurb 11" 128GB Good
];

const results = [];
for (const u of testUrls) {
  await tool.navigate({ tabId, url: u });
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 2500 });
  const info = await browserjs(tabId, () => {
    // Look for price on page
    const p1 = document.querySelector('[data-test="product-price"]')?.innerText;
    const p2 = document.querySelector('[data-test="@web/Price/Large"]')?.innerText;
    const h1 = document.querySelector('h1')?.innerText;
